Now let me understand the protocol. The `protocol.mjs` handles JSON-RPC requests. For `tools/call`, it calls `callTool(req.params.name, req.params.arguments||{})`. Errors thrown become JSON-RPC errors with code -32602.

Let me write the server. The requirements:
- Expose `inventory_search` with required string `query` and optional integer `limit` from 1 to 10.
- Search product names case-insensitively, limit results, return a text content response.
- Reject invalid arguments and unknown tools.

Let me write `server.mjs`:

```js
import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory products by name. Returns matching products as text.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query matched against product names (case-insensitive).' },
          limit: { type: 'integer', minimum: 1, maximum: 10, description: 'Maximum number of results to return (1-10). Defaults to 10.' }
        },
        required: ['query']
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { query, limit } = args;
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }
  let resolvedLimit;
  if (limit === undefined) {
    resolvedLimit = 10;
  } else {
    if (!Number.isInteger(limit)) {
      throw new Error('limit must be an integer');
    }
    if (limit < 1 || limit > 10) {
      throw new Error('limit must be between 1 and 10');
    }
    resolvedLimit = limit;
  }
  const q = query.toLowerCase();
  const matches = products.filter(p => p.name.toLowerCase().includes(q)).slice(0, resolvedLimit);
  const text = matches.length
    ? matches.map(p => `${p.id}: ${p.name}`).join('\n')
    : 'No matching products found.';
  return { content: [{ type: 'text', text }] };
}
